<template>
  <section class="designer-shell">
    <div class="designer-header">
      <div class="designer-title-group">
        <button class="designer-back" title="返回流程定义" @click="emit('close')">‹</button>
        <div>
          <div class="designer-breadcrumb">流程中心 / 流程定义 / 设计器</div>
          <div class="designer-title-line">
            <input v-model="process.name" class="designer-name-input" @input="fieldChanged('修改流程名称')" />
            <span class="version-badge">草稿 V{{ process.version }}</span>
            <span :class="['designer-save-state', saveStateClass]"><i></i>{{ saveState }}</span>
          </div>
        </div>
      </div>
      <div class="designer-header-actions">
        <button class="toolbar-button" @click="undo" :disabled="!undoStack.length" title="撤销">↶ <span>撤销</span></button>
        <button class="toolbar-button" @click="redo" :disabled="!redoStack.length" title="重做">↷ <span>重做</span></button>
        <span class="toolbar-divider"></span>
        <button class="toolbar-button" @click="runValidation">✓ 校验 <em v-if="validation.length">{{ validation.length }}</em></button>
        <button class="toolbar-button" @click="showPreview = true">▷ 预览</button>
        <button class="button-ghost" @click="saveDesign(false)">保存草稿</button>
        <button class="button-primary" @click="publishDesign">发布流程</button>
      </div>
    </div>

    <div class="designer-meta-bar">
      <div class="meta-item"><span>流程编码</span><b>{{ process.code }}</b></div>
      <div class="meta-item"><span>归属分类</span><b>{{ process.category || '未分类' }}</b></div>
      <div class="meta-item"><span>流程负责人</span><b>{{ process.owner || 'admin' }}</b></div>
      <div class="meta-item"><span>节点</span><b>{{ nodes.length }}</b></div>
      <div class="meta-item"><span>连线</span><b>{{ edges.length }}</b></div>
      <div class="meta-spacer"></div>
      <span v-if="connectingFrom" class="connect-tip">请选择目标节点完成连线 · Esc 取消</span>
      <button class="meta-link" @click="bottomPanel = bottomPanel === 'json' ? '' : 'json'">查看 JSON</button>
      <button class="meta-link" @click="openProcessSettings">流程设置</button>
    </div>

    <div class="designer-workspace" :class="{ 'palette-collapsed': paletteCollapsed }">
      <aside class="designer-palette">
        <div class="panel-title-row">
          <div><h3>节点工具箱</h3><small>拖拽节点到画布</small></div>
          <button class="panel-collapse" :title="paletteCollapsed ? '展开工具箱' : '收起工具箱'" @click="paletteCollapsed = !paletteCollapsed">{{ paletteCollapsed ? '›' : '‹' }}</button>
        </div>
        <div class="palette-search"><span>⌕</span><input v-model="paletteKeyword" placeholder="搜索节点" /></div>
        <div v-for="group in filteredPalette" :key="group.name" class="palette-group">
          <div class="palette-group-title"><span>{{ group.name }}</span><i>{{ group.items.length }}</i></div>
          <button v-for="item in group.items" :key="item.type" class="palette-node" draggable="true" @dragstart="dragPalette($event, item)" @click="addFromPalette(item.type)">
            <span :class="['palette-icon', `tone-${item.tone}`]">{{ item.icon }}</span>
            <span class="palette-copy"><b>{{ item.label }}</b><small>{{ item.description }}</small></span>
            <span class="palette-add">+</span>
          </button>
        </div>
        <div class="palette-foot"><span class="keyboard-key">D</span> 快速复制节点 <span class="keyboard-key">⌫</span> 删除节点</div>
      </aside>

      <section class="designer-canvas-panel">
        <div class="canvas-toolbar">
          <div class="canvas-mode"><button :class="{active: canvasMode === 'select'}" @click="canvasMode = 'select'">↖ 选择</button><button :class="{active: canvasMode === 'connect'}" @click="canvasMode = 'connect'">⌁ 连线</button><button :class="{active: canvasMode === 'pan'}" @click="canvasMode = 'pan'">✥ 画布</button></div>
          <div class="canvas-toolbar-actions"><span class="canvas-help">拖拽空白区域平移 · 滚轮缩放</span><button @click="fitCanvas">适应画布</button><button class="toolbar-icon-button" @click="centerCanvas" title="将流程定位到画布中心">◎</button><button @click="zoomOut">−</button><span class="zoom-value">{{ Math.round(zoom * 100) }}%</span><button @click="zoomIn">＋</button></div>
        </div>
        <div ref="canvasViewport" :class="['canvas-viewport', `mode-${canvasMode}`, { 'is-panning': isPanning } ]" @pointerdown="handleViewportPointerDown" @dragover.prevent @drop="dropNode" @wheel.prevent="zoomByWheel" @contextmenu.prevent>
          <div class="canvas-ruler horizontal"><span v-for="mark in rulerMarks" :key="`h-${mark}`" :style="{left: `${mark}px`}">{{ mark }}</span></div>
          <div class="canvas-ruler vertical"><span v-for="mark in rulerMarks" :key="`v-${mark}`" :style="{top: `${mark}px`}">{{ mark }}</span></div>
          <div class="canvas-stage" :style="stageStyle">
            <svg class="connection-layer" :width="stageWidth" :height="stageHeight" aria-label="流程连线">
              <defs>
                <pattern id="smallGrid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M 20 0 L 0 0 0 20" fill="none" stroke="#e8eef5" stroke-width="1" /></pattern>
                <pattern id="largeGrid" width="100" height="100" patternUnits="userSpaceOnUse"><rect width="100" height="100" fill="url(#smallGrid)" /><path d="M 100 0 L 0 0 0 100" fill="none" stroke="#dbe5ef" stroke-width="1" /></pattern>
                <marker id="arrowHead" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#7e9bb8" /></marker>
                <marker id="arrowHeadSelected" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#236bd3" /></marker>
              </defs>
              <rect width="100%" height="100%" fill="url(#largeGrid)" />
              <g v-for="edge in edges" :key="edge.id">
                <path :d="edgePath(edge)" class="connection-hit" @click.stop="selectEdge(edge)" />
                <path :d="edgePath(edge)" :class="['connection-line', {selected: selectedEdgeId === edge.id}]" :marker-end="selectedEdgeId === edge.id ? 'url(#arrowHeadSelected)' : 'url(#arrowHead)'" @click.stop="selectEdge(edge)" />
                <text v-if="edge.condition" :x="edgeLabelPoint(edge).x" :y="edgeLabelPoint(edge).y" class="connection-label" @click.stop="selectEdge(edge)">{{ edge.condition }}</text>
              </g>
              <path v-if="connectingFrom" :d="connectionPreviewPath" class="connection-preview" />
            </svg>
          <div v-for="node in nodes" :key="node.id" :class="nodeClasses(node)" :style="nodeStyle(node)" role="button" tabindex="0" :aria-label="`${node.label}，${nodeMeta(node.type).label}`" @pointerdown.stop="startNodeDrag($event, node)" @click.stop="selectNode(node)" @keydown.enter.stop="selectNode(node)">
              <span class="node-status-dot"></span>
              <span class="node-symbol">{{ nodeMeta(node.type).icon }}</span>
              <span class="node-content"><b>{{ node.label || nodeMeta(node.type).label }}</b><small>{{ nodeSubtitle(node) }}</small></span>
              <button v-for="port in ports" :key="`port-${node.id}-${port}`" :class="['node-port', `port-${port}`, portClass(node)]" :title="portTitle(node, port)" @pointerdown.stop="handlePortPointerDown($event, node, port)" @pointerup.stop="handlePortPointerUp($event, node, port)" @click.stop="handlePortClick(node, port)"></button>
              <span v-if="selectedNodeId === node.id" class="node-quick-actions"><button @click.stop="duplicateNode(node)">⧉</button><button @click.stop="removeNode(node)">×</button></span>
            </div>
          </div>
          <div class="canvas-empty-hint" v-if="!nodes.length"><b>从左侧拖入第一个节点</b><small>建议先放置开始事件，再逐步配置审批与业务节点</small></div>
          <div class="minimap"><div class="minimap-title"><span>画布导航</span><span>{{ Math.round(zoom * 100) }}%</span></div><div class="minimap-stage" @pointerdown.stop="jumpToMiniMap"><span v-for="node in nodes" :key="`mini-${node.id}`" :class="['mini-node', `mini-${node.type}`]" :style="miniNodeStyle(node)"></span><div class="mini-viewport" :style="miniViewportStyle"></div></div></div>
        </div>
        <div class="designer-bottom-bar">
          <div class="bottom-tabs"><button :class="{active: bottomPanel === 'validation'}" @click="toggleBottomPanel('validation')">流程校验 <i :class="{danger: hasValidationErrors}">{{ validation.length }}</i></button><button :class="{active: bottomPanel === 'changes'}" @click="toggleBottomPanel('changes')">变更记录 <i>{{ history.length }}</i></button><button :class="{active: bottomPanel === 'json'}" @click="toggleBottomPanel('json')">定义 JSON</button></div>
          <div class="bottom-shortcuts"><span><kbd>⌘</kbd><kbd>S</kbd> 保存</span><span><kbd>⌘</kbd><kbd>Z</kbd> 撤销</span><span><kbd>Esc</kbd> 取消连线</span></div>
        </div>
        <div v-if="bottomPanel" class="bottom-panel-content">
          <div v-if="bottomPanel === 'validation'" class="validation-panel"><div class="validation-summary"><span :class="['validation-icon', {ok: !hasValidationErrors}]">{{ hasValidationErrors ? '!' : '✓' }}</span><div><b>{{ hasValidationErrors ? '发现需要处理的问题' : '流程结构校验通过' }}</b><small>{{ hasValidationErrors ? '发布前请处理阻断项；警告项可按业务规则决定是否修正。' : '当前流程具备完整的开始、审批和结束路径，可以进入发布审核。' }}</small></div><button class="button-ghost" @click="runValidation">重新校验</button></div><div v-if="validation.length" class="validation-list"><div v-for="item in validation" :key="item.id" :class="['validation-row', item.level]"><span>{{ item.level === 'error' ? '×' : '!' }}</span><div><b>{{ item.title }}</b><small>{{ item.message }}</small></div><button @click="focusIssue(item)">定位</button></div></div><div v-else class="validation-clear">没有发现结构问题。可继续完善节点表单、权限与超时策略。</div></div>
          <div v-else-if="bottomPanel === 'changes'" class="change-panel"><div class="change-head"><b>本次编辑会话</b><span>共 {{ history.length }} 项变更</span></div><div v-if="history.length" class="change-list"><div v-for="item in history.slice(0, 12)" :key="item.id" class="change-row"><span class="change-dot"></span><div><b>{{ item.label }}</b><small>{{ item.time }}</small></div></div></div><div v-else class="validation-clear">还没有编辑记录，拖入或修改节点后会显示在这里。</div></div>
          <div v-else class="json-panel"><div class="json-head"><b>当前流程定义快照</b><button class="meta-link" @click="copyJson">复制 JSON</button></div><pre>{{ definitionJson }}</pre></div>
        </div>
      </section>

      <aside class="designer-inspector">
        <div class="inspector-tabs"><button :class="{active: inspectorTab === 'properties'}" @click="inspectorTab = 'properties'">属性</button><button :class="{active: inspectorTab === 'variables'}" @click="inspectorTab = 'variables'">变量 <i>{{ variables.length }}</i></button><button :class="{active: inspectorTab === 'audit'}" @click="inspectorTab = 'audit'">审计</button></div>
        <div v-if="inspectorTab === 'properties'" class="inspector-scroll">
          <div v-if="selectedNode" class="inspector-heading"><span :class="['inspector-symbol', `tone-${nodeMeta(selectedNode.type).tone}`]">{{ nodeMeta(selectedNode.type).icon }}</span><div><b>{{ nodeMeta(selectedNode.type).label }}</b><small>{{ selectedNode.id }}</small></div><button class="inspector-delete" @click="removeNode(selectedNode)">⌫</button></div>
          <div v-else-if="selectedEdge" class="inspector-heading"><span class="inspector-symbol tone-blue">⌁</span><div><b>条件连线</b><small>{{ selectedEdge.source }} → {{ selectedEdge.target }}</small></div><button class="inspector-delete" @click="removeEdge(selectedEdge)">⌫</button></div>
          <div v-else class="inspector-heading"><span class="inspector-symbol tone-indigo">⌘</span><div><b>流程属性</b><small>未选择节点</small></div></div>

          <template v-if="selectedNode">
            <div class="property-section"><div class="section-label">基础信息 <span>Basic</span></div><label class="field-label">节点名称<input v-model="selectedNode.label" @input="fieldChanged('修改节点名称')" /></label><label class="field-label">节点编码<input v-model="selectedNode.code" @input="fieldChanged('修改节点编码')" /></label><label class="field-label">节点说明<textarea v-model="selectedNode.description" rows="2" placeholder="描述该节点的业务目的" @input="fieldChanged('修改节点说明')"></textarea></label></div>
            <div v-if="selectedNode.type === 'userTask'" class="property-section"><div class="section-label">审批人配置 <span>Assignee</span></div><label class="field-label">分配方式<select v-model="selectedNode.assigneeMode" @change="fieldChanged('修改分配方式')"><option value="group">候选角色</option><option value="user">指定用户</option><option value="expression">表达式</option></select></label><label v-if="selectedNode.assigneeMode === 'group'" class="field-label">候选角色<input v-model="selectedNode.candidateGroups" placeholder="planner, admin" @input="fieldChanged('修改候选角色')" /><small class="field-hint">多个角色使用逗号分隔，任一角色均可签收。</small></label><label v-else-if="selectedNode.assigneeMode === 'user'" class="field-label">指定用户<input v-model="selectedNode.assignee" placeholder="输入用户编码" @input="fieldChanged('修改指定用户')" /></label><label v-else class="field-label">用户表达式<input v-model="selectedNode.assigneeExpression" placeholder="${initiator}" @input="fieldChanged('修改用户表达式')" /></label><label class="field-label">绑定表单<select v-model="selectedNode.formCode" @change="fieldChanged('绑定节点表单')"><option value="">不绑定表单</option><option value="FORM-WORK-ORDER-APPROVAL">工单发布审批表</option><option value="FORM-PURCHASE-001">采购申请表</option><option value="FORM-QUALITY-001">质量异常处置表</option></select></label><div class="inline-fields"><label class="field-label">处理时限<input v-model.number="selectedNode.dueDays" type="number" min="0" @input="fieldChanged('修改处理时限')" /></label><label class="field-label">超时策略<select v-model="selectedNode.timeoutAction" @change="fieldChanged('修改超时策略')"><option value="remind">提醒</option><option value="escalate">升级</option><option value="autoReject">自动驳回</option></select></label></div><label class="switch-row"><input v-model="selectedNode.requireComment" type="checkbox" @change="fieldChanged('修改审批意见策略')" /><span class="switch-ui"></span><span>完成时必须填写审批意见</span></label><label class="switch-row"><input v-model="selectedNode.allowTransfer" type="checkbox" @change="fieldChanged('修改转办策略')" /><span class="switch-ui"></span><span>允许处理人转办</span></label></div>
            <div v-if="selectedNode.type === 'serviceTask'" class="property-section"><div class="section-label">业务动作 <span>Service</span></div><label class="field-label">服务键<input v-model="selectedNode.serviceKey" placeholder="business.setStatus / workOrder.updateStatus" @input="fieldChanged('修改服务键')" /><small class="field-hint">服务键是后端业务动作注册表的稳定标识，执行结果会写入流程变量。</small></label><label class="field-label">执行方式<select v-model="selectedNode.serviceType" @change="fieldChanged('修改执行方式')"><option value="delegate">后端业务动作</option><option value="expression">表达式</option><option value="webhook">Webhook</option></select></label><label class="field-label">失败重试<select v-model="selectedNode.retry" @change="fieldChanged('修改重试策略')"><option value="0">不重试</option><option value="3">失败后重试 3 次</option><option value="5">失败后重试 5 次</option></select></label></div>
            <div v-if="selectedNode.type === 'subprocess'" class="property-section"><div class="section-label">子流程调用 <span>Call activity</span></div><label class="field-label">被调用流程编码<input v-model="selectedNode.processRef" placeholder="inventory.receive" @input="fieldChanged('修改子流程编码')" /><small class="field-hint">被调用流程需要先发布；运行时会按流程编码进入独立的子流程实例。</small></label></div>
            <div v-if="selectedNode.type === 'exclusiveGateway' || selectedNode.type === 'inclusiveGateway'" class="property-section"><div class="section-label">网关策略 <span>Gateway</span></div><label class="field-label">默认路径<select v-model="selectedNode.defaultEdge" @change="fieldChanged('修改默认路径')"><option value="">未设置</option><option v-for="edge in outgoingEdges(selectedNode.id)" :key="edge.id" :value="edge.id">{{ edge.condition || edge.id }}</option></select></label><label class="switch-row"><input v-model="selectedNode.waitForAll" type="checkbox" @change="fieldChanged('修改网关等待策略')" /><span class="switch-ui"></span><span>等待所有分支完成</span></label><p class="property-callout">在连线上设置条件表达式，网关会按照变量值选择下一条路径。</p></div>
            <div v-if="selectedNode.type === 'timerEvent'" class="property-section"><div class="section-label">定时策略 <span>Timer</span></div><label class="field-label">定时类型<select v-model="selectedNode.timerType" @change="fieldChanged('修改定时类型')"><option value="duration">持续时间</option><option value="date">指定时间</option><option value="cycle">循环周期</option></select></label><label class="field-label">定时表达式<input v-model="selectedNode.timerValue" placeholder="PT2H / R3/PT1D" @input="fieldChanged('修改定时表达式')" /></label></div>
            <div v-if="selectedNode.type === 'messageEvent'" class="property-section"><div class="section-label">消息触发 <span>Message</span></div><label class="field-label">消息名称<input v-model="selectedNode.messageName" placeholder="workOrder.approved" @input="fieldChanged('修改消息名称')" /></label><label class="field-label">消息变量<input v-model="selectedNode.messageVariable" placeholder="businessId" @input="fieldChanged('修改消息变量')" /></label></div>
          </template>

          <template v-else-if="selectedEdge">
            <div class="property-section"><div class="section-label">连线条件 <span>Condition</span></div><label class="field-label">条件名称<input v-model="selectedEdge.condition" placeholder="审批通过" @input="fieldChanged('修改条件名称')" /></label><label class="field-label">表达式<textarea v-model="selectedEdge.expression" rows="3" placeholder="${approved == true}" @input="fieldChanged('修改条件表达式')"></textarea></label><label class="switch-row"><input v-model="selectedEdge.isDefault" type="checkbox" @change="fieldChanged('设置默认路径')" /><span class="switch-ui"></span><span>设为默认路径</span></label></div>
          </template>

          <template v-else>
            <div class="property-section"><div class="section-label">流程标识 <span>Identity</span></div><label class="field-label">流程编码<input v-model="process.code" :disabled="!isNewDefinition && Boolean(definitionCode)" placeholder="例如 purchase_to_stock" @input="fieldChanged('修改流程编码')" /><small class="field-hint">只能使用英文、数字和下划线；发布后作为业务接口的稳定标识。</small></label><label class="field-label">流程名称<input v-model="process.name" @input="fieldChanged('修改流程名称')" /></label><div class="inline-fields"><label class="field-label">流程类型<select v-model="process.processType" @change="fieldChanged('修改流程类型')"><option value="BUSINESS">业务流程</option><option value="APPROVAL">审批流程</option></select></label><label class="field-label">触发方式<select v-model="process.triggerType" @change="fieldChanged('修改触发方式')"><option value="MANUAL">人工发起</option><option value="EVENT">业务事件</option><option value="SCHEDULE">定时触发</option></select></label></div><label class="field-label">业务分类<select v-model="process.category" @change="fieldChanged('修改业务分类')"><option>生产制造</option><option>仓储物流</option><option>质量管理</option><option>采购协同</option><option>通用审批</option><option>跨业务协同</option></select></label><label class="field-label">流程描述<textarea v-model="process.description" rows="3" @input="fieldChanged('修改流程描述')"></textarea></label></div><div class="property-section"><div class="section-label">运行设置 <span>Runtime</span></div><label class="field-label">实例标题模板<input v-model="process.titleTemplate" placeholder="${businessType} - ${businessId}" @input="fieldChanged('修改实例标题模板')" /></label><label class="switch-row"><input v-model="process.allowWithdraw" type="checkbox" @change="fieldChanged('修改撤回策略')" /><span class="switch-ui"></span><span>允许发起人撤回</span></label><label class="switch-row"><input v-model="process.enableHistory" type="checkbox" @change="fieldChanged('修改历史记录策略')" /><span class="switch-ui"></span><span>保留完整审批轨迹</span></label></div>
          </template>
        </div>
        <div v-else-if="inspectorTab === 'variables'" class="inspector-scroll"><div class="inspector-heading"><span class="inspector-symbol tone-green">⌘</span><div><b>流程变量</b><small>Variables</small></div><button class="icon-plus" @click="addVariable">+</button></div><p class="inspector-intro">变量贯穿流程实例生命周期，可用于网关条件、表单回填和服务节点参数。</p><div v-for="(variable, index) in variables" :key="variable.id" class="variable-card"><div class="variable-index">{{ String(index + 1).padStart(2, '0') }}</div><div class="variable-body"><input v-model="variable.key" placeholder="变量编码" @input="fieldChanged('修改变量编码')" /><input v-model="variable.label" placeholder="显示名称" @input="fieldChanged('修改变量名称')" /><div class="inline-fields"><select v-model="variable.type" @change="fieldChanged('修改变量类型')"><option>string</option><option>number</option><option>boolean</option><option>date</option><option>json</option></select><input v-model="variable.defaultValue" placeholder="默认值" @input="fieldChanged('修改变量默认值')" /></div></div><button class="variable-remove" @click="removeVariable(variable)">×</button></div><div v-if="!variables.length" class="empty-inspector"><span>⌘</span><b>暂无流程变量</b><small>点击右上角 + 添加第一个变量</small></div></div>
        <div v-else class="inspector-scroll audit-panel"><div class="inspector-heading"><span class="inspector-symbol tone-violet">◎</span><div><b>审计信息</b><small>Audit trail</small></div></div><div class="audit-card"><span>创建人</span><b>{{ process.createdBy || 'admin' }}</b></div><div class="audit-card"><span>最后修改</span><b>{{ process.updatedBy || 'admin' }}</b><small>{{ saveState === '已保存' ? '刚刚保存' : '当前编辑会话' }}</small></div><div class="audit-card"><span>版本状态</span><b class="audit-green">草稿</b><small>发布后将生成新版本</small></div><div class="audit-divider"></div><div class="audit-event" v-for="item in history.slice(0, 6)" :key="`audit-${item.id}`"><i></i><div><b>{{ item.label }}</b><small>{{ item.time }}</small></div></div></div>
      </aside>
    </div>

