function selectNode(node) { if (connectingFrom.value && connectingFrom.value.id !== node.id) { finishConnection(node); return } selectedNodeId.value = node.id; selectedEdgeId.value = ''; if (canvasMode.value === 'connect' && node.type !== 'end') beginConnection(node, connectionSourcePort.value) }
