function dropNode(event) { const type = event.dataTransfer?.getData('application/polaris-node') || event.dataTransfer?.getData('text/plain'); if (!type) return; const point = canvasPoint(event); addNodeAt(type, point.x - nodeSize({ type }).width / 2, point.y - 20) }
function addFromPalette(type) { addNodeAt(type, 260 + nodes.value.length * 18, 120 + (nodes.value.length % 4) * 110) }
function addNodeAt(type, x, y) { const node = baseNode(type, Math.round(x / 10) * 10, Math.round(y / 10) * 10, { code: `${type}_${nodes.value.length + 1}` }); perform(`新增节点：${nodeMeta(type).label}`, () => nodes.value.push(node)); selectedNodeId.value = node.id; selectedEdgeId.value = ''; runValidation(false); bottomPanel.value = '' }
function duplicateNode(node) { const copy = baseNode(node.type, node.x + 35, node.y + 35, { ...JSON.parse(JSON.stringify(node)), id: `${node.type}_${Date.now()}`, code: `${node.code}_copy`, label: `${node.label}（副本）` }); perform(`复制节点：${node.label}`, () => nodes.value.push(copy)); selectedNodeId.value = copy.id }
function removeNode(node) { if (!node) return; perform(`删除节点：${node.label}`, () => { nodes.value = nodes.value.filter(item => item.id !== node.id); edges.value = edges.value.filter(edge => edge.source !== node.id && edge.target !== node.id) }); selectedNodeId.value = ''; selectedEdgeId.value = '' }
