function incomingEdges(id) { return edges.value.filter(edge => edge.target === id) }
function runValidation(openPanel = true) { validation.value = []; const add = (level, title, message, nodeId = '') => validation.value.push({ id: `${level}_${title}_${nodeId}`, level, title, message, nodeId }); const starts = nodes.value.filter(node => node.type === 'start'); const ends = nodes.value.filter(node => node.type === 'end'); if (!process.code.trim()) add('error', '流程编码不能为空', '请在流程属性中填写唯一的流程编码。'); if (!process.name.trim()) add('error', '流程名称不能为空', '请给当前流程填写一个便于业务识别的名称。'); if (starts.length !== 1) add('error', '开始事件数量不正确', `当前有 ${starts.length} 个开始事件，流程必须且只能有 1 个开始事件。`); if (!ends.length) add('error', '缺少结束事件', '至少配置一个结束事件，确保实例可以正常结束。'); const ids = new Set(); nodes.value.forEach(node => { if (ids.has(node.id)) add('error', '节点编码重复', `节点 ${node.label} 的 ID 重复，请重新生成。`, node.id); ids.add(node.id); if (node.type === 'userTask' && node.assigneeMode === 'group' && !node.candidateGroups?.trim()) add('error', '审批人未配置', `${node.label} 没有配置候选角色，运行时将无法生成待办。`, node.id); if (node.type === 'userTask' && node.assigneeMode === 'user' && !node.assignee?.trim()) add('error', '指定用户为空', `${node.label} 需要指定一个有效的用户编码。`, node.id); if (node.type === 'serviceTask' && !node.serviceKey?.trim()) add('error', '服务键未配置', `${node.label} 没有服务键，无法调用业务服务。`, node.id); if (isGateway(node.type) && outgoingEdges(node.id).length < 2) add('warning', '网关分支不足', `${node.label} 当前只有 ${outgoingEdges(node.id).length} 条出边，建议至少配置两条分支。`, node.id); if (node.type !== 'start' && !incomingEdges(node.id).length) add('warning', '节点未接入流程', `${node.label} 没有入边，运行时不会被触达。`, node.id); if (node.type !== 'end' && !outgoingEdges(node.id).length) add('warning', '节点没有后续路径', `${node.label} 没有出边，可能导致流程停留在此节点。`, node.id) }); edges.value.forEach(edge => { if (!nodes.value.some(node => node.id === edge.source) || !nodes.value.some(node => node.id === edge.target)) add('error', '存在无效连线', `连线 ${edge.id} 指向不存在的节点。`); if (edge.source === edge.target) add('error', '连线不能自循环', `连线 ${edge.id} 的起点和终点相同。`) }); if (openPanel) bottomPanel.value = 'validation'; saveState.value = validation.value.some(item => item.level === 'error') ? '待修复' : '已校验'; return validation.value }
function focusIssue(item) { if (item.nodeId) { selectedNodeId.value = item.nodeId; selectedEdgeId.value = ''; } }
function graphBounds() { if (!nodes.value.length) return { minX: 0, maxX: stageWidth, minY: 0, maxY: stageHeight }; return { minX: Math.min(...nodes.value.map(node => node.x)), maxX: Math.max(...nodes.value.map(node => node.x + nodeSize(node).width)), minY: Math.min(...nodes.value.map(node => node.y)), maxY: Math.max(...nodes.value.map(node => node.y + nodeSize(node).height)) } }
function fitCanvas() { if (!nodes.value.length) return; const bounds = graphBounds(); const viewport = canvasViewport.value; const availableWidth = viewport?.clientWidth || 900; const availableHeight = viewport?.clientHeight || 620; const padding = 96; zoom.value = Math.min(1.2, Math.max(0.45, Math.min((availableWidth - padding * 2) / Math.max(1, bounds.maxX - bounds.minX), (availableHeight - padding * 2) / Math.max(1, bounds.maxY - bounds.minY)))); centerCanvas() }
function centerCanvas() { const bounds = graphBounds(); const availableWidth = canvasViewport.value?.clientWidth || 900; const availableHeight = canvasViewport.value?.clientHeight || 620; pan.x = (availableWidth - (bounds.maxX - bounds.minX) * zoom.value) / 2 - bounds.minX * zoom.value; pan.y = (availableHeight - (bounds.maxY - bounds.minY) * zoom.value) / 2 - bounds.minY * zoom.value }
function zoomIn() { zoom.value = Math.min(2, Number((zoom.value + 0.1).toFixed(2))) }
function zoomOut() { zoom.value = Math.max(0.35, Number((zoom.value - 0.1).toFixed(2))) }
function zoomByWheel(event) { const rect = canvasViewport.value?.getBoundingClientRect(); if (!rect) return; const before = canvasPoint(event); const step = event.deltaY > 0 ? -0.06 : 0.06; const nextZoom = Math.min(2, Math.max(0.35, Number((zoom.value + step).toFixed(2)))); if (nextZoom === zoom.value) return; zoom.value = nextZoom; pan.x = event.clientX - rect.left - before.x * nextZoom; pan.y = event.clientY - rect.top - before.y * nextZoom }
function jumpToMiniMap(event) { const rect = event.currentTarget.getBoundingClientRect(); const worldX = ((event.clientX - rect.left) / rect.width) * stageWidth; const worldY = ((event.clientY - rect.top) / rect.height) * stageHeight; const viewport = canvasViewport.value; pan.x = (viewport?.clientWidth || 900) / 2 - worldX * zoom.value; pan.y = (viewport?.clientHeight || 620) / 2 - worldY * zoom.value }
function toggleBottomPanel(panel) { bottomPanel.value = bottomPanel.value === panel ? '' : panel }
function openProcessSettings() { selectedNodeId.value = ''; selectedEdgeId.value = ''; inspectorTab.value = 'properties' }
function addVariable() { perform('新增流程变量', () => variables.value.push({ id: `var_${Date.now()}`, key: '', label: '', type: 'string', defaultValue: '' })); inspectorTab.value = 'variables' }
function removeVariable(variable) { perform(`删除流程变量：${variable.key || '未命名'}`, () => { variables.value = variables.value.filter(item => item.id !== variable.id) }) }
async function copyJson() { try { await navigator.clipboard.writeText(definitionJson.value); saveState.value = 'JSON 已复制' } catch { saveState.value = '复制失败' } }

function storageKey(code = process.code) { return `polaris-bpm-design:${code}` }
function applyDesign(data) { const design = data?.design || data; if (!design || !Array.isArray(design.nodes)) return false; Object.assign(process, { ...defaultProcess, ...(design.process || {}), processType: design.process?.processType || design.processType || process.processType, triggerType: design.process?.triggerType || design.triggerType || process.triggerType, code: design.process?.code || design.processCode || process.code, name: design.process?.name || design.processName || process.name }); nodes.value = design.nodes.map(node => ({ ...nodeDefaults(node.type), ...node })); edges.value = Array.isArray(design.edges) ? design.edges : []; variables.value = Array.isArray(design.variables) ? design.variables : []; definitionCode.value = process.code; dirty.value = false; saveState.value = '已保存'; validation.value = []; return true }
async function loadDesign() { const definition = props.definition || {}; const code = definition.process_code || definition.processCode || definition.code || (definition.isNew ? process.code : 'workOrderApproval'); definitionCode.value = definition.isNew ? '' : code; Object.assign(process, { ...defaultProcess, code, name: definition.process_name || definition.processName || (definition.isNew ? '新业务流程' : defaultProcess.name), processType: definition.process_type || definition.processType || (definition.isNew ? 'BUSINESS' : defaultProcess.processType), triggerType: definition.trigger_type || definition.triggerType || 'MANUAL', category: definition.category || (definition.isNew ? '通用业务' : defaultProcess.category), version: Number(definition.version || 1) }); if (definition.isNew) { nodes.value = createDefaultNodes(); edges.value = createDefaultEdges(); variables.value = []; validation.value = []; dirty.value = true; saveState.value = '未保存'; window.setTimeout(fitCanvas, 80); return } const remote = await request(`/bpm/process-designs/${encodeURIComponent(code)}`); let localData = null; try { const local = localStorage.getItem(storageKey(code)); localData = local ? JSON.parse(local) : null } catch { localData = null } if (!applyDesign(remote) && !(localData && applyDesign(localData))) { nodes.value = createDefaultNodes(); edges.value = createDefaultEdges(); validation.value = []; dirty.value = true; saveState.value = '未保存' } window.setTimeout(fitCanvas, 80) }
async function saveDesign(auto = false) { if (saving.value) return; saving.value = true; saveState.value = auto ? '自动保存中' : '保存中'; const body = { processCode: process.code, processName: process.name, description: process.description, category: process.category, processType: process.processType, triggerType: process.triggerType, owner: process.owner, version: process.version, process: { ...process }, nodes: nodes.value, edges: edges.value, variables: variables.value, status: 'DRAFT' }; try { await request(`/bpm/process-designs/${encodeURIComponent(process.code)}`, { method: 'PUT', body: JSON.stringify(body), allowFallback: false }); definitionCode.value = process.code; localStorage.setItem(storageKey(), JSON.stringify(body)); saveState.value = '已保存'; dirty.value = false } catch (error) { localStorage.setItem(storageKey(), JSON.stringify(body)); saveState.value = '保存失败（已保留本地副本）'; if (!auto) console.error(error) } finally { saving.value = false } }
async function publishDesign() { runValidation(); if (hasValidationErrors.value) { saveState.value = '待修复'; return } const body = { processCode: process.code, processName: process.name, description: process.description, category: process.category, processType: process.processType, triggerType: process.triggerType, owner: process.owner, version: process.version, process: { ...process }, nodes: nodes.value, edges: edges.value, variables: variables.value, status: 'PUBLISHED' }; saving.value = true; saveState.value = '发布中'; try { await request(`/bpm/process-designs/${encodeURIComponent(process.code)}/publish`, { method: 'POST', body: JSON.stringify(body), allowFallback: false }); definitionCode.value = process.code; localStorage.setItem(storageKey(), JSON.stringify(body)); saveState.value = '已发布'; dirty.value = false } catch (error) { saveState.value = '发布失败'; console.error(error) } finally { saving.value = false } }
function onKeydown(event) { const tag = document.activeElement?.tagName; if (event.code === 'Space' && !['INPUT', 'TEXTAREA', 'SELECT'].includes(tag)) { spacePressed.value = true; event.preventDefault() } if (!['INPUT', 'TEXTAREA', 'SELECT'].includes(tag) && event.key.toLowerCase() === 'c') { canvasMode.value = 'connect'; event.preventDefault() } if (!['INPUT', 'TEXTAREA', 'SELECT'].includes(tag) && event.key.toLowerCase() === 'v') { canvasMode.value = 'select'; connectingFrom.value = null; event.preventDefault() } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 's') { event.preventDefault(); saveDesign(false) } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'z' && tag !== 'INPUT' && tag !== 'TEXTAREA') { event.preventDefault(); event.shiftKey ? redo() : undo() } if (event.key === 'Escape') { connectingFrom.value = null; canvasMode.value = 'select'; if (showPreview.value) showPreview.value = false } if ((event.key === 'Delete' || event.key === 'Backspace') && !['INPUT', 'TEXTAREA', 'SELECT'].includes(tag)) { if (selectedNode.value) removeNode(selectedNode.value); else if (selectedEdge.value) removeEdge(selectedEdge.value) } }
function onKeyup(event) { if (event.code === 'Space') spacePressed.value = false }

function trackConnection(event) { if (connectingFrom.value && canvasViewport.value) connectionCursor.value = canvasPoint(event) }
watch(() => props.definition, loadDesign, { immediate: true })
onMounted(() => { window.addEventListener('keydown', onKeydown); window.addEventListener('keyup', onKeyup); window.addEventListener('pointermove', trackConnection); window.setTimeout(() => runValidation(false), 120) })
onBeforeUnmount(() => { window.clearTimeout(autoSaveTimer); window.removeEventListener('keydown', onKeydown); window.removeEventListener('keyup', onKeyup); window.removeEventListener('pointermove', trackConnection); window.removeEventListener('pointermove', moveNode); window.removeEventListener('pointermove', movePan) })
</script>
